              "\u041A\u0430\u0436\u0434\u044B\u0439 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0441 1\u20135 \u043A\u043E\u0441\u0442\u044F\u043C\u0438, \u043E\u0431\u044B\u0447\u043D\u043E \u0441 \u043F\u044F\u0442\u044C\u044E. \u0412\u0438\u0434\u043D\u044B \u0442\u043E\u043B\u044C\u043A\u043E \u0441\u0432\u043E\u0438 \u043A\u043E\u0441\u0442\u0438. \u0421\u0442\u0430\u0432\u043A\u0430 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u043A\u043E\u0441\u0442\u0435\u0439 \u043E\u0434\u043D\u043E\u0439 \u0433\u0440\u0430\u043D\u0438 \u043F\u043E\u0434 \u0432\u0441\u0435\u043C\u0438 \u0441\u0442\u0430\u043A\u0430\u043D\u0430\u043C\u0438 \u0432\u043C\u0435\u0441\u0442\u0435. \u041F\u043E\u0432\u044B\u0441\u044C \u0441\u0442\u0430\u0432\u043A\u0443 \u0438\u043B\u0438 \u043E\u0441\u043F\u043E\u0440\u044C \u0435\u0451. \u0417\u0430 \u043B\u043E\u0436\u043D\u0443\u044E \u0441\u0442\u0430\u0432\u043A\u0443 \u043A\u043E\u0441\u0442\u044C \u0442\u0435\u0440\u044F\u0435\u0442 \u0435\u0451 \u0430\u0432\u0442\u043E\u0440; \u0437\u0430 \u043E\u0441\u043F\u0430\u0440\u0438\u0432\u0430\u043D\u0438\u0435 \u0432\u0435\u0440\u043D\u043E\u0439 \u2014 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u044E\u0449\u0438\u0439. \u0412\u0435\u0440\u043D\u0430\u044F \u0441\u0442\u0430\u0432\u043A\u0430 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043D\u0430\u043B\u0438\u0447\u0438\u0435 \u043D\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u0433\u043E \u0447\u0438\u0441\u043B\u0430 \u043A\u043E\u0441\u0442\u0435\u0439. \u0411\u0435\u0437 \u043A\u043E\u0441\u0442\u0435\u0439 \u0438\u0433\u0440\u043E\u043A \u0432\u044B\u0431\u044B\u0432\u0430\u0435\u0442. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0441 \u043A\u043E\u0441\u0442\u044F\u043C\u0438."),
            rule_section(:variants, "\u0412\u0430\u0440\u0438\u0430\u043D\u0442\u044B \u0438 \u0442\u043E\u0447\u043D\u044B\u0435 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0438",
              "\u0412 \u043A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u043E\u043C \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0435 \u043D\u0435\u0442 \u0434\u0436\u043E\u043A\u0435\u0440\u043E\u0432. \u0423\u0432\u0435\u043B\u0438\u0447\u044C \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0441 \u043B\u044E\u0431\u043E\u0439 \u0433\u0440\u0430\u043D\u044C\u044E \u043B\u0438\u0431\u043E \u043E\u0441\u0442\u0430\u0432\u044C \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0438 \u043F\u043E\u0432\u044B\u0441\u044C \u0433\u0440\u0430\u043D\u044C. \u0421\u0442\u0438\u043B\u044C Red Dead \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u00AB\u0422\u043E\u0447\u043D\u043E\u00BB: \u043F\u0440\u0438 \u0443\u0441\u043F\u0435\u0445\u0435 \u0432\u0441\u0435 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0442\u0435\u0440\u044F\u044E\u0442 \u043A\u043E\u0441\u0442\u044C, \u043F\u0440\u0438 \u043E\u0448\u0438\u0431\u043A\u0435 \u2014 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u044E\u0449\u0438\u0439. \u0412 Perudo \u0435\u0434\u0438\u043D\u0438\u0446\u044B \u0441\u043B\u0443\u0436\u0430\u0442 \u0434\u0436\u043E\u043A\u0435\u0440\u0430\u043C\u0438 \u0434\u043B\u044F \u0434\u0440\u0443\u0433\u0438\u0445 \u0433\u0440\u0430\u043D\u0435\u0439. \u041E\u0431\u044B\u0447\u043D\u044B\u0439 \u0440\u0430\u0443\u043D\u0434 \u043D\u0435\u043B\u044C\u0437\u044F \u043D\u0430\u0447\u0438\u043D\u0430\u0442\u044C \u0441 \u0435\u0434\u0438\u043D\u0438\u0446. \u041F\u0435\u0440\u0435\u0445\u043E\u0434 \u043D\u0430 \u0435\u0434\u0438\u043D\u0438\u0446\u044B \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043F\u043E\u043B\u043E\u0432\u0438\u043D\u0443 \u043F\u0440\u043E\u0448\u043B\u043E\u0433\u043E \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u0430 \u0441 \u043E\u043A\u0440\u0443\u0433\u043B\u0435\u043D\u0438\u0435\u043C \u0432\u0432\u0435\u0440\u0445; \u043E\u0431\u0440\u0430\u0442\u043D\u043E \u2014 \u0443\u0434\u0432\u043E\u0435\u043D\u043D\u043E\u0435 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u043F\u043B\u044E\u0441 \u043E\u0434\u0438\u043D. \u0421\u0442\u0430\u0432\u043A\u0443 \u043D\u0430 \u0435\u0434\u0438\u043D\u0438\u0446\u044B \u043F\u043E\u0432\u044B\u0448\u0430\u044E\u0442 \u0443\u0432\u0435\u043B\u0438\u0447\u0435\u043D\u0438\u0435\u043C \u0438\u0445 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u0430."),
            rule_section(:special, "Palifico, Calza \u0438 \u0441\u043A\u0440\u044B\u0442\u044B\u0435 \u0431\u0440\u043E\u0441\u043A\u0438",
              "\u041D\u0435\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0435 Palifico \u0432 Perudo \u0434\u043B\u0438\u0442\u0441\u044F \u043E\u0434\u0438\u043D \u0440\u0430\u0443\u043D\u0434, \u043A\u043E\u0433\u0434\u0430 \u043D\u0430\u0447\u0438\u043D\u0430\u044E\u0449\u0438\u0439 \u0432\u043F\u0435\u0440\u0432\u044B\u0435 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0441 \u043E\u0434\u043D\u043E\u0439 \u043A\u043E\u0441\u0442\u044C\u044E \u0438 \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u0431\u043E\u043B\u044C\u0448\u0435 \u0434\u0432\u0443\u0445. \u0415\u0434\u0438\u043D\u0438\u0446\u044B \u043F\u0435\u0440\u0435\u0441\u0442\u0430\u044E\u0442 \u0431\u044B\u0442\u044C \u0434\u0436\u043E\u043A\u0435\u0440\u0430\u043C\u0438; \u043C\u0435\u043D\u044F\u0442\u044C \u0433\u0440\u0430\u043D\u044C \u043C\u043E\u0433\u0443\u0442 \u043B\u0438\u0448\u044C \u0443\u0436\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0432\u0448\u0438\u0435 Palifico. \u041D\u0435\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u0443\u044E Calza \u043C\u043E\u0436\u0435\u0442 \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u043B\u044E\u0431\u043E\u0439, \u043A\u0440\u043E\u043C\u0435 \u0430\u0432\u0442\u043E\u0440\u0430 \u0441\u0442\u0430\u0432\u043A\u0438, \u0434\u043E \u043F\u0440\u0438\u043D\u044F\u0442\u0438\u044F \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0441\u0442\u0430\u0432\u043A\u0438. \u0423\u0441\u043F\u0435\u0445 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u043A\u043E\u0441\u0442\u044C \u0434\u043E \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u043B\u0438\u043C\u0438\u0442\u0430, \u043E\u0448\u0438\u0431\u043A\u0430 \u043E\u0442\u043D\u0438\u043C\u0430\u0435\u0442 \u043A\u043E\u0441\u0442\u044C. \u041F\u043E\u0441\u043B\u0435 \u043F\u043E\u0442\u0435\u0440\u0438 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u043F\u0440\u043E\u0438\u0433\u0440\u0430\u0432\u0448\u0438\u0439 \u043B\u0438\u0431\u043E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0439\u0441\u044F \u0438\u0433\u0440\u043E\u043A. \u041F\u043E\u0441\u043B\u0435 \u0443\u0441\u043F\u0435\u0448\u043D\u043E\u0433\u043E \u00AB\u0422\u043E\u0447\u043D\u043E\u00BB Red Dead \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u044E\u0449\u0438\u0439, \u043F\u043E\u0441\u043B\u0435 \u0432\u0435\u0440\u043D\u043E\u0439 Calza \u2014 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u043F\u0440\u043E\u0438\u0433\u0440\u0430\u0432\u0448\u0438\u0439."),
            rule_section(:privacy, "\u041F\u0440\u0438\u0432\u0430\u0442\u043D\u043E\u0441\u0442\u044C \u043A\u043E\u0441\u0442\u0435\u0439",
              "\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0438\u0433\u0440\u043E\u043A\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u0430 \u043F\u043E \u0441\u0435\u043A\u0440\u0435\u0442\u043D\u044B\u043C \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F\u043C, \u0437\u0430\u0442\u0435\u043C \u0441\u0435\u0440\u0432\u0435\u0440 \u0434\u0430\u0451\u0442 \u043D\u043E\u0432\u043E\u0435 \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u043E\u0435 \u0437\u0435\u0440\u043D\u043E. \u0412\u043C\u0435\u0441\u0442\u0435 \u043E\u043D\u0438 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u044E\u0442 \u0441\u043A\u0440\u044B\u0442\u044B\u0435 \u043A\u043E\u0441\u0442\u0438. \u0421\u0435\u043A\u0440\u0435\u0442\u044B \u0440\u0430\u0441\u043A\u0440\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u044E\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u043E\u0441\u043B\u0435 \u0432\u044B\u0437\u043E\u0432\u0430. \u0411\u043E\u0442\u044B \u0437\u043D\u0430\u044E\u0442 \u0441\u0432\u043E\u0439 \u0441\u0442\u0430\u043A\u0430\u043D \u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0435 \u0441\u0442\u0430\u0432\u043A\u0438. \u0418\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439 \u0442\u043E\u0442 \u0436\u0435 \u043F\u0440\u043E\u0444\u0438\u043B\u044C Elten, \u0447\u0442\u043E\u0431\u044B \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u0441\u0435\u043A\u0440\u0435\u0442\u044B. \u0421\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0435 \u0438\u0433\u0440\u044B \u0438 \u043F\u0435\u0440\u0435\u0434\u0430\u0447\u0430 \u043D\u0435\u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D\u043D\u043E\u0433\u043E \u0441\u0435\u043A\u0440\u0435\u0442\u0430 \u0431\u043B\u043E\u043A\u0438\u0440\u0443\u044E\u0442\u0441\u044F; \u0434\u0440\u0443\u0433\u043E\u0433\u043E \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u0430 \u0437\u0430\u043C\u0435\u043D\u0438\u0442\u044C \u043C\u043E\u0436\u043D\u043E."),
            rule_section(:controls, "\u0423\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438 \u0438 Enter \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442 \u043C\u0438\u043D\u0438\u043C\u0430\u043B\u044C\u043D\u0443\u044E \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0443\u044E \u0441\u0442\u0430\u0432\u043A\u0443 \u0434\u043B\u044F \u0433\u0440\u0430\u043D\u0438 \u043B\u0438\u0431\u043E \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0443. B \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0444\u043E\u0440\u043C\u0443 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u0430 \u0438 \u0433\u0440\u0430\u043D\u0438. K \u043E\u0441\u043F\u0430\u0440\u0438\u0432\u0430\u0435\u0442 \u0431\u043B\u0435\u0444, D \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442 \u00AB\u0422\u043E\u0447\u043D\u043E\u00BB, \u043A\u043E\u0433\u0434\u0430 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E. V \u0447\u0438\u0442\u0430\u0435\u0442 \u0441\u0432\u043E\u0438 \u043A\u043E\u0441\u0442\u0438, L \u2014 \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u0441\u0442\u0430\u0432\u043A\u0443. \u0411\u0440\u043E\u0441\u043A\u0438 \u0438 \u0440\u0430\u0441\u043A\u0440\u044B\u0442\u0438\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u044E\u0442\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u043E\u0431\u0449\u0438\u043C \u0438\u0441\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u0435\u043C. F1 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u043A\u043E\u043C\u0430\u043D\u0434\u044B, Ctrl+F1 \u2014 \u043F\u0440\u0430\u0432\u0438\u043B\u0430. \u0427\u0430\u0442, \u0438\u0441\u0442\u043E\u0440\u0438\u044F \u0438 \u0433\u0440\u043E\u043C\u043A\u043E\u0441\u0442\u044C \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u044E\u0442 \u043E\u0431\u0449\u0438\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0438.")
